"""Execute and judge code generated by the COCO editing SFT adapter."""
import argparse
import base64
import json
import re
import sys
from pathlib import Path

from openai import AzureOpenAI

ROOT = Path('/mnt/bn/embodied-lf3/masiyuan')
sys.path.insert(0, str(ROOT / 'qwen_pixel/scripts'))
from build_teacher_magicbrush import run_code  # noqa: E402

PROMPT = '''You are evaluating an image editing result.
Image 1: source image.
Image 2: model prediction.
Instruction: {instruction}
Score 1-5 for instruction_adherence, preservation, visual_quality, and set pass true only if the edit is clearly correct and usable.
Return JSON only: {{"instruction_adherence":1,"preservation":1,"visual_quality":1,"pass":false,"reason":"..."}}
'''


def extract_code(text):
    match = re.search(r'<code>(.*?)</code>', text, re.S)
    if match:
        return match.group(1).strip()
    match = re.search(r'(def edit\(image\):.*)', text, re.S)
    return match.group(1).strip() if match else ''


def b64(path):
    return base64.b64encode(Path(path).read_bytes()).decode()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--generations', required=True)
    parser.add_argument('--data', required=True)
    parser.add_argument('--out', required=True)
    args = parser.parse_args()
    gens = [json.loads(line) for line in Path(args.generations).read_text().splitlines() if line.strip()]
    rows = {r['id']: r for r in [json.loads(line) for line in Path(args.data).read_text().splitlines() if line.strip()]}
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    (out / 'executions').mkdir(exist_ok=True)
    client = AzureOpenAI(api_key=__import__("os").environ["QWEN_PIXEL_PROXY_KEY"],
                         api_version='2023-07-01-preview',
                         azure_endpoint='https://search.bytedance.net/gpt/openapi/online/multimodal/crawl',
                         timeout=240)
    results = []
    for gen in gens:
        row = rows.get(gen['id'])
        if not row:
            continue
        code = extract_code(gen['text'])
        result = {'id': gen['id'], 'instruction': row['instruction'],
                  'code_present': bool(code), 'code_length': len(code)}
        if not code:
            result.update(execution='skipped', pass_=False)
            results.append(result)
            continue
        execution = run_code(code, Path(row['image']), out / 'executions' / f"{gen['id']}.png")
        result['execution'] = execution['status']
        result['error'] = execution.get('error', '')
        if execution['status'] == 'passed':
            pred = out / 'executions' / f"{gen['id']}.png"
            content = [
                {'type': 'text', 'text': PROMPT.format(instruction=row['instruction'])},
                {'type': 'image_url', 'image_url': {'url': 'data:image/png;base64,' + b64(row['image'])}},
                {'type': 'image_url', 'image_url': {'url': 'data:image/png;base64,' + b64(pred)}},
            ]
            response = client.chat.completions.create(
                model='gpt-5.5-2026-04-24', messages=[{'role': 'user', 'content': content}],
                max_completion_tokens=8192, reasoning_effort='low')
            text = (response.choices[0].message.content or '').strip()
            text = re.sub(r'^```(?:json)?\s*', '', text)
            text = re.sub(r'\s*```$', '', text)
            try:
                result['judge'] = json.loads(text)
            except Exception:
                result['judge'] = {'raw': text}
        results.append(result)
        print(json.dumps(result, ensure_ascii=False), flush=True)
    (out / 'results.jsonl').write_text(''.join(json.dumps(r, ensure_ascii=False) + '\n' for r in results))
    summary = {
        'total': len(results),
        'code_present': sum(r.get('code_present', False) for r in results),
        'execution_passed': sum(r.get('execution') == 'passed' for r in results),
        'judge_pass': sum(r.get('judge', {}).get('pass', False) for r in results),
        'pass_rate': sum(r.get('judge', {}).get('pass', False) for r in results) / len(results) if results else 0,
    }
    (out / 'summary.json').write_text(json.dumps(summary, indent=2))
    print(json.dumps(summary, indent=2))


if __name__ == '__main__':
    main()
